function SearchPage() {
  const [query, setQuery] = useState("");

  return (
    <>
      <SearchInput value={query} onChange={setQuery} />
      <SearchSummary query={query} />
    </>
  );
}

function SearchInput({ value, onChange }: Props) {
  return <input value={value} onChange={(event) => onChange(event.target.value)} />;
}

function SearchSummary({ query }: { query: string }) {
  return <p>Searching for: {query || "(nothing yet)"}</p>;
}

import { createContext, useContext, useState } from "react";

type Theme = "light" | "dark";
type ThemeContextValue = { theme: Theme; toggleTheme: () => void };
const ThemeContext = createContext<ThemeContextValue | null>(null);

function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setTheme] = useState<Theme>("light");
  const value = {
    theme,
    toggleTheme: () => setTheme((current) => current === "light" ? "dark" : "light"),
  };
  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
}

function useTheme() {
  const value = useContext(ThemeContext);
  if (!value) throw new Error("useTheme must be used within ThemeProvider");
  return value;
}

import { useState } from "react";
function useCounter() {
  const [count, setCount] = useState(0);
  return { count, increment: () => setCount((current) => current + 1) };
}
function CounterA() {
  const { count, increment } = useCounter();
  return <button onClick={increment}>A: {count}</button>;
}
function CounterB() {
  const { count, increment } = useCounter();
  return <button onClick={increment}>B: {count}</button>;
}

type Book = {
  id: string;
  title: string;
  author: string;
  year: number;
  isRead: boolean;
};
type BookAction =
  | { type: "ADD_BOOK"; book: Book }
  | { type: "TOGGLE_READ"; id: string }
  | { type: "DELETE_BOOK"; id: string };

function bookReducer(state: Book[], action: BookAction): Book[] {
  switch (action.type) {
    case "ADD_BOOK":
      return [...state, action.book];
    case "TOGGLE_READ":
      return state.map((book) =>
        book.id === action.id ? { ...book, isRead: !book.isRead } : book
      );
    case "DELETE_BOOK":
      return state.filter((book) => book.id !== action.id);
    default: {
      const exhaustiveCheck: never = action;
      return exhaustiveCheck;
    }
  }
}

import { createContext, useContext, useReducer, type Dispatch, type ReactNode } from "react";

type Preferences = {
  theme: "light" | "dark";
  compactMode: boolean;
};
type PreferencesAction =
  | { type: "toggle-theme" }
  | { type: "toggle-compact" };

function preferencesReducer(
  state: Preferences,
  action: PreferencesAction,
): Preferences {
  switch (action.type) {
    case "toggle-theme":
      return { ...state, theme: state.theme === "light" ? "dark" : "light" };
    case "toggle-compact":
      return { ...state, compactMode: !state.compactMode };
    default: {
      const exhaustiveCheck: never = action;
      return exhaustiveCheck;
    }
  }
}

type PreferencesContextValue = {
  state: Preferences;
  dispatch: Dispatch<PreferencesAction>;
};
const PreferencesContext = createContext<PreferencesContextValue | null>(null);

function PreferencesProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(preferencesReducer, {
    theme: "light",
    compactMode: false,
  });
  return (
    <PreferencesContext.Provider value={{ state, dispatch }}>
      {children}
    </PreferencesContext.Provider>
  );
}

function usePreferences() {
  const context = useContext(PreferencesContext);
  if (!context) throw new Error("usePreferences must be inside PreferencesProvider");
  return context;
}

